    liveShields.delete(state.shield);
    state.shield.remove();
    state.shield = null;
  }
  if (state.shield == null) {
    state.isShieldFull = isFull || state.viewport + state.layer > 0;
    state.shield = addShield(layer, state.isShieldFull);
