    touchAction: 'pan-y pinch-zoom',
    paddingInline: spacingVars['--spacing-2'],
    paddingBlock: spacingVars['--spacing-2'],
  },
});

const dynamicStyles = stylex.create({
  // The requested width, never more than 85 % of the viewport: on a narrow
