                isStart && styles.drawerStart,
                isStart && isOpen && styles.drawerStartOpen,
                !isStart && styles.drawerEnd,
                !isStart && isOpen && styles.drawerEndOpen,
              )}>
              {/* Header — content + close button */}
              <div
