const PASSIVE_ROLES = new Set([
  'article',
  'banner',
  'complementary',
  'contentinfo',
  'definition',
  'directory',
  'document',
  'figure',
  'form',
  'generic',
  'group',
  'heading',
  'list',
  'listitem',
  'main',
  'navigation',
  'none',
  'note',
  'paragraph',
  'presentation',
  'region',
  'section',
  'status',
  'table',
  'term',
]);

