      viewport.tabIndex = -1;
      restoreTabStop = () => {
        if (viewport.getAttribute('tabindex') === '-1') {
          if (tabIndex == null) {
            viewport.removeAttribute('tabindex');
          } else {
            viewport.setAttribute('tabindex', tabIndex);
