    left: `${-element.scrollLeft}px`,
    boxSizing: 'border-box',
    width: `${element.clientWidth}px`,
    height: 'auto',
    padding: getComputedStyle(element).padding,
    // The holder is the visible part, inside the border.
    borderWidth: '0px',
    margin: '0px',
