    if (!isSubscribed) {
      return;
    }
    isSubscribed = false;
    const current = streams.get(view)?.get(type);
    if (current == null) {
      return;
    }
    const index = current.subscribers.indexOf(subscriber);
    if (index !== -1) {
      current.subscribers.splice(index, 1);
    }
    register(view, type, current);
    if (current.subscribers.length === 0) {
